CREATE OR REPLACE FUNCTION public.pos_complete_return(p_shift_id uuid, p_operator_id uuid, p_order_id uuid, p_client_op_id text, p_items jsonb, p_reason text, p_authorization_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_shift public.pos_shifts;
  v_order public.commerce_orders;
  v_return public.pos_returns;
  v_request record;
  v_order_item public.commerce_order_items;
  v_sku public.inv_skus;
  v_returned_quantity integer;
  v_refund_total numeric := 0;
BEGIN
  SELECT * INTO v_return FROM public.pos_returns WHERE client_op_id = p_client_op_id;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'return_id', v_return.id, 'refund_total', v_return.refund_total, 'replayed', true
    );
  END IF;

  SELECT * INTO v_shift FROM public.pos_shifts WHERE id = p_shift_id FOR UPDATE;
  IF NOT FOUND OR v_shift.status <> 'open' OR v_shift.operator_id <> p_operator_id THEN
    RAISE EXCEPTION 'POS shift is not available';
  END IF;
  SELECT * INTO v_order FROM public.commerce_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND OR v_order.source_channel <> 'pos' OR v_order.payment_status <> 'paid' THEN
    RAISE EXCEPTION 'POS order is not returnable';
  END IF;
  IF v_order.sale_location_id <> v_shift.location_id THEN
    RAISE EXCEPTION 'order belongs to another location';
  END IF;

  INSERT INTO public.pos_returns(
    order_id, shift_id, location_id, operator_id, authorization_id,
    reason, status, client_op_id, completed_at
  ) VALUES (
    p_order_id, p_shift_id, v_shift.location_id, p_operator_id, p_authorization_id,
    p_reason, 'completed', p_client_op_id, now()
  ) RETURNING * INTO v_return;

  FOR v_request IN
    SELECT item.order_item_id, item.quantity
      FROM jsonb_to_recordset(p_items) AS item(order_item_id uuid, quantity integer)
  LOOP
    SELECT * INTO v_order_item
      FROM public.commerce_order_items
     WHERE id = v_request.order_item_id
       AND order_id = p_order_id;
    IF NOT FOUND OR v_request.quantity < 1 OR v_request.quantity > v_order_item.quantity THEN
      RAISE EXCEPTION 'return item quantity is invalid';
    END IF;

    SELECT COALESCE(sum(return_item.quantity), 0)::integer
      INTO v_returned_quantity
      FROM public.pos_return_items return_item
      JOIN public.pos_returns sale_return ON sale_return.id = return_item.return_id
     WHERE return_item.order_item_id = v_order_item.id
       AND sale_return.status IN ('pending', 'completed');
    IF v_returned_quantity + v_request.quantity > v_order_item.quantity THEN
      RAISE EXCEPTION 'return quantity exceeds remaining quantity';
    END IF;

    SELECT * INTO v_sku
      FROM public.inv_skus
     WHERE id = v_order_item.sku_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'return SKU not found';
    END IF;

    INSERT INTO public.pos_return_items(
      return_id, order_item_id, sku_id, quantity, refund_amount,
      physical_status, inspection_status
    ) VALUES (
      v_return.id, v_order_item.id, v_order_item.sku_id, v_request.quantity,
      round(v_order_item.line_total / v_order_item.quantity * v_request.quantity, 2),
      'received',
      CASE
        WHEN v_sku.kind = 'single'
         AND NOT v_sku.is_custom_price
         AND v_order_item.epc IS NULL
        THEN 'passed'
        ELSE 'pending'
      END
    );
    v_refund_total := v_refund_total
      + round(v_order_item.line_total / v_order_item.quantity * v_request.quantity, 2);

    IF v_sku.kind = 'single'
       AND NOT v_sku.is_custom_price
       AND v_order_item.epc IS NULL THEN
      PERFORM public.inv_apply_movement(
        v_order_item.sku_id, v_shift.location_id, v_request.quantity,
        'pos_return', v_return.id, NULL, p_client_op_id
      );
    END IF;
  END LOOP;

  UPDATE public.pos_returns SET refund_total = v_refund_total WHERE id = v_return.id;
  UPDATE public.commerce_orders
     SET order_status = 'after_sale',
         metadata = metadata || jsonb_build_object('latest_pos_return_id', v_return.id),
         updated_at = now()
   WHERE id = p_order_id;

  RETURN jsonb_build_object(
    'return_id', v_return.id,
    'refund_total', v_refund_total,
    'inspection_required', EXISTS (
      SELECT 1 FROM public.pos_return_items
       WHERE return_id = v_return.id AND inspection_status = 'pending'
    ),
    'replayed', false
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.pos_complete_sale(p_shift_id uuid, p_operator_id uuid, p_client_op_id text, p_items jsonb, p_tenders jsonb, p_customer_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_shift public.pos_shifts;
  v_order public.commerce_orders;
  v_sku public.inv_skus;
  v_item record;
  v_component record;
  v_tender record;
  v_stock integer;
  v_available integer;
  v_required integer;
  v_unit_price numeric;
  v_subtotal numeric := 0;
  v_tender_total numeric := 0;
  v_payment_id uuid;
  v_receipt_no text;
  v_category_name text;
  v_subcategory_name text;
  v_items_payload jsonb;
BEGIN
  IF p_client_op_id IS NULL OR btrim(p_client_op_id) = '' THEN
    RAISE EXCEPTION 'client operation id is required';
  END IF;
  IF jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'sale requires at least one item';
  END IF;
  IF jsonb_typeof(p_tenders) <> 'array' OR jsonb_array_length(p_tenders) = 0 THEN
    RAISE EXCEPTION 'sale requires at least one tender';
  END IF;

  SELECT * INTO v_order
    FROM public.commerce_orders
   WHERE source_channel = 'pos'
     AND idempotency_key = p_client_op_id;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'order_id', v_order.id,
      'order_no', v_order.order_no,
      'replayed', true,
      'total_amount', v_order.total_amount
    );
  END IF;

  SELECT * INTO v_shift
    FROM public.pos_shifts
   WHERE id = p_shift_id
   FOR UPDATE;
  IF NOT FOUND OR v_shift.status <> 'open' THEN RAISE EXCEPTION 'POS shift is not open'; END IF;
  IF v_shift.operator_id <> p_operator_id THEN RAISE EXCEPTION 'POS shift belongs to another operator'; END IF;

  FOR v_item IN
    SELECT (elem->>'sku_id')::uuid AS sku_id, sum((elem->>'quantity')::integer) AS quantity
      FROM jsonb_array_elements(p_items) AS elem
     GROUP BY 1
     ORDER BY 1
  LOOP
    IF v_item.sku_id IS NULL OR v_item.quantity IS NULL OR v_item.quantity < 1 OR v_item.quantity > 999 THEN
      RAISE EXCEPTION 'sale item quantity is invalid';
    END IF;
    SELECT * INTO v_sku FROM public.inv_skus WHERE id = v_item.sku_id FOR UPDATE;
    IF NOT FOUND OR v_sku.status <> 'active' OR NOT v_sku.is_display THEN
      RAISE EXCEPTION 'SKU % is not sellable', v_item.sku_id;
    END IF;
    IF v_sku.kind = 'single' AND v_sku.is_custom_price AND v_item.quantity <> 1 THEN
      RAISE EXCEPTION 'custom SKU quantity must be one';
    END IF;
    v_available := public.sales_sku_available_qty(v_sku.id, v_shift.location_id);
    IF v_available < v_item.quantity THEN
      RAISE EXCEPTION 'SKU % has insufficient available stock', v_sku.id;
    END IF;
    v_subtotal := v_subtotal + v_sku.price_tier * v_item.quantity;
  END LOOP;

  FOR v_tender IN
    SELECT tender.provider, tender.amount, tender.provider_transaction_id
      FROM jsonb_to_recordset(p_tenders)
        AS tender(provider text, amount numeric, provider_transaction_id text)
  LOOP
    IF v_tender.provider NOT IN ('cash','wechat','alipay','bank_card','store_credit','manual') THEN
      RAISE EXCEPTION 'unsupported tender provider';
    END IF;
    IF v_tender.amount IS NULL OR v_tender.amount <= 0 THEN
      RAISE EXCEPTION 'tender amount is invalid';
    END IF;
    v_tender_total := v_tender_total + v_tender.amount;
  END LOOP;
  IF round(v_tender_total, 2) <> round(v_subtotal, 2) THEN
    RAISE EXCEPTION 'tender total does not match sale total';
  END IF;

  INSERT INTO public.commerce_orders (
    user_id, source_channel, fulfillment_method, sale_location_id, operator_id,
    customer_id, pos_shift_id, payment_status, order_status, subtotal,
    total_amount, recipient_name, recipient_phone, shipping_address,
    courier_provider, courier_service_code, idempotency_key,
    reservation_expires_at, paid_at, completed_at, customer_note
  ) VALUES (
    NULL, 'pos', 'carryout', v_shift.location_id, p_operator_id,
    p_customer_id, p_shift_id, 'paid', 'completed', v_subtotal,
    v_subtotal, NULL, NULL, NULL, NULL, NULL, p_client_op_id,
    now(), now(), now(), p_note
  ) RETURNING * INTO v_order;

  FOR v_item IN
    SELECT (elem->>'sku_id')::uuid AS sku_id,
           (elem->>'quantity')::integer AS quantity,
           nullif(btrim(coalesce(elem->>'subcategory_code', '')), '') AS subcategory_code,
           ord
      FROM jsonb_array_elements(p_items) WITH ORDINALITY AS t(elem, ord)
     ORDER BY ord
  LOOP
    SELECT * INTO v_sku FROM public.inv_skus WHERE id = v_item.sku_id FOR UPDATE;
    v_unit_price := v_sku.price_tier;

    SELECT name INTO v_category_name FROM public.inv_categories WHERE code = v_sku.category;

    v_subcategory_name := NULL;
    IF v_item.subcategory_code IS NOT NULL THEN
      SELECT child.name INTO v_subcategory_name
        FROM public.inv_categories child
        JOIN public.inv_categories root ON root.id = child.parent_id
       WHERE child.code = v_item.subcategory_code
         AND child.is_active
         AND root.code = v_sku.category;
      IF v_subcategory_name IS NULL THEN
        RAISE EXCEPTION 'subcategory % is not valid for SKU %', v_item.subcategory_code, v_sku.id;
      END IF;
    END IF;

    INSERT INTO public.commerce_order_items (
      order_id, listing_id, sku_id, location_id, epc, title_snapshot,
      image_snapshot, condition_snapshot, unit_price, quantity, line_total,
      category_code, category_name_snapshot, subcategory_code, subcategory_name_snapshot
    )
    VALUES (
      v_order.id, NULL, v_sku.id, v_shift.location_id,
      CASE WHEN v_sku.kind = 'single' AND v_sku.is_custom_price THEN v_sku.epc ELSE NULL END,
      v_sku.name, v_sku.image_url, v_sku.grade, v_unit_price, v_item.quantity,
      v_unit_price * v_item.quantity,
      v_sku.category, coalesce(v_category_name, v_sku.category),
      v_item.subcategory_code, v_subcategory_name
    );

    IF v_sku.kind = 'bundle' THEN
      IF jsonb_typeof(v_sku.bundle_items) <> 'array' OR jsonb_array_length(v_sku.bundle_items) = 0 THEN
        RAISE EXCEPTION 'bundle SKU % has no components', v_sku.id;
      END IF;
      FOR v_component IN
        SELECT component.sku_id, component.qty
          FROM jsonb_to_recordset(v_sku.bundle_items) AS component(sku_id uuid, qty integer)
         ORDER BY component.sku_id
      LOOP
        v_required := v_item.quantity * v_component.qty;
        SELECT qty INTO v_stock
          FROM public.inv_stocks
         WHERE sku_id = v_component.sku_id AND location_id = v_shift.location_id
         FOR UPDATE;
        IF coalesce(v_stock, 0) < v_required THEN
          RAISE EXCEPTION 'bundle component % is out of stock', v_component.sku_id;
        END IF;
        PERFORM public.inv_apply_movement(
          v_component.sku_id, v_shift.location_id, -v_required,
          'pos_sale', v_order.id, NULL, p_client_op_id
        );
      END LOOP;
    ELSIF v_sku.inventory_policy = 'unlimited' THEN
      NULL;
    ELSE
      SELECT qty INTO v_stock
        FROM public.inv_stocks
       WHERE sku_id = v_sku.id AND location_id = v_shift.location_id
       FOR UPDATE;
      IF coalesce(v_stock, 0) < v_item.quantity THEN
        RAISE EXCEPTION 'SKU % is out of stock', v_sku.id;
      END IF;
      PERFORM public.inv_apply_movement(
        v_sku.id, v_shift.location_id, -v_item.quantity,
        'pos_sale', v_order.id,
        CASE WHEN v_sku.is_custom_price THEN v_sku.epc ELSE NULL END,
        p_client_op_id
      );
      IF v_sku.is_custom_price THEN
        UPDATE public.inv_skus SET sales_state = 'sold', updated_at = now() WHERE id = v_sku.id;
        UPDATE public.inv_epcs SET status = 'sold', current_location_id = NULL, last_seen_at = now()
         WHERE epc = v_sku.epc;
        UPDATE public.commerce_listings SET status = 'sold', sold_at = now(), updated_at = now()
         WHERE sku_id = v_sku.id AND status IN ('published', 'reserved');
      END IF;
    END IF;
  END LOOP;

  FOR v_tender IN
    SELECT tender.provider, tender.amount, tender.provider_transaction_id
      FROM jsonb_to_recordset(p_tenders)
        AS tender(provider text, amount numeric, provider_transaction_id text)
  LOOP
    INSERT INTO public.commerce_payments (
      order_id, provider, status, amount, provider_transaction_id, idempotency_key, paid_at
    ) VALUES (
      v_order.id, v_tender.provider, 'succeeded', v_tender.amount,
      v_tender.provider_transaction_id, p_client_op_id || ':' || v_tender.provider, now()
    ) RETURNING id INTO v_payment_id;
    INSERT INTO public.commerce_payment_events (
      payment_id, provider, provider_event_id, event_type,
      signature_verified, payload, processing_status, processed_at
    ) VALUES (
      v_payment_id, v_tender.provider,
      coalesce(v_tender.provider_transaction_id, p_client_op_id || ':' || v_tender.provider),
      'pos_payment_succeeded', true,
      jsonb_build_object('amount', v_tender.amount, 'shift_id', p_shift_id),
      'processed', now()
    );
    IF v_tender.provider = 'cash' THEN
      INSERT INTO public.pos_cash_movements (shift_id, order_id, type, amount, reason, operator_id)
      VALUES (p_shift_id, v_order.id, 'sale', v_tender.amount, 'POS sale', p_operator_id);
    END IF;
  END LOOP;

  SELECT jsonb_agg(jsonb_build_object(
           'sku_id', item.sku_id,
           'title', item.title_snapshot,
           'unit_price', item.unit_price,
           'quantity', item.quantity,
           'line_total', item.line_total,
           'category_code', item.category_code,
           'category_name', item.category_name_snapshot,
           'subcategory_code', item.subcategory_code,
           'subcategory_name', item.subcategory_name_snapshot
         ) ORDER BY item.created_at, item.id)
    INTO v_items_payload
    FROM public.commerce_order_items item
   WHERE item.order_id = v_order.id;

  v_receipt_no := (
    SELECT receipt_prefix FROM public.pos_registers WHERE id = v_shift.register_id
  ) || '-' || to_char(now(), 'YYYYMMDD') || '-' || right(v_order.order_no, 6);
  INSERT INTO public.pos_receipts (order_id, shift_id, receipt_no, payload)
  VALUES (
    v_order.id, p_shift_id, v_receipt_no,
    jsonb_build_object(
      'order_no', v_order.order_no,
      'receipt_no', v_receipt_no,
      'total_amount', v_order.total_amount,
      'paid_at', v_order.paid_at,
      'items', coalesce(v_items_payload, '[]'::jsonb)
    )
  );

  RETURN jsonb_build_object(
    'order_id', v_order.id,
    'order_no', v_order.order_no,
    'receipt_no', v_receipt_no,
    'replayed', false,
    'total_amount', v_order.total_amount,
    'items', coalesce(v_items_payload, '[]'::jsonb)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.pos_complete_sale_v2(p_shift_id uuid, p_operator_id uuid, p_client_op_id text, p_items jsonb, p_tenders jsonb, p_customer_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text, p_discount_snapshot jsonb DEFAULT '{}'::jsonb, p_benefit_snapshot jsonb DEFAULT '{}'::jsonb, p_authorization_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item record;
  v_sku public.inv_skus;
  v_subtotal numeric := 0;
  v_eligible numeric := 0;
  v_discount numeric := 0;
  v_payable numeric := 0;
  v_tender_total numeric := 0;
  v_discount_type text;
  v_discount_value numeric;
  v_discount_provider text;
  v_discount_transaction text := 'POS-DISCOUNT:' || p_client_op_id;
  v_augmented_tenders jsonb;
  v_result jsonb;
  v_order_id uuid;
  v_authorization public.pos_authorizations;
BEGIN
  IF jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'sale requires at least one item';
  END IF;

  FOR v_item IN
    SELECT item.sku_id, item.quantity
      FROM jsonb_to_recordset(p_items) AS item(sku_id uuid, quantity integer)
  LOOP
    SELECT * INTO v_sku FROM public.inv_skus WHERE id = v_item.sku_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'SKU % not found', v_item.sku_id; END IF;
    v_subtotal := v_subtotal + v_sku.price_tier * v_item.quantity;
    IF v_sku.discount_eligible AND v_sku.sale_ownership = 'owned' THEN
      v_eligible := v_eligible + v_sku.price_tier * v_item.quantity;
    END IF;
  END LOOP;

  v_discount_type := nullif(p_discount_snapshot->>'type', '');
  v_discount_value := coalesce((p_discount_snapshot->>'value')::numeric, 0);
  IF v_discount_type IS NULL THEN
    v_discount := 0;
  ELSIF v_discount_type = 'amount' THEN
    v_discount := v_discount_value;
  ELSIF v_discount_type = 'percentage' THEN
    IF v_discount_value < 0 OR v_discount_value > 100 THEN
      RAISE EXCEPTION 'percentage discount is invalid';
    END IF;
    v_discount := round(v_eligible * (1 - v_discount_value / 100), 2);
  ELSIF v_discount_type = 'final_price' THEN
    v_discount := v_subtotal - v_discount_value;
  ELSE
    RAISE EXCEPTION 'discount type is invalid';
  END IF;

  v_discount := round(v_discount, 2);
  IF v_discount < 0 OR v_discount > v_eligible THEN
    RAISE EXCEPTION 'discount exceeds eligible amount';
  END IF;
  v_payable := round(v_subtotal - v_discount, 2);

  SELECT coalesce(sum(tender.amount), 0)
    INTO v_tender_total
    FROM jsonb_to_recordset(p_tenders)
      AS tender(provider text, amount numeric, provider_transaction_id text);
  IF round(v_tender_total, 2) <> v_payable THEN
    RAISE EXCEPTION 'tender total does not match payable total';
  END IF;

  IF p_authorization_id IS NOT NULL THEN
    SELECT * INTO v_authorization
      FROM public.pos_authorizations
     WHERE id = p_authorization_id
       AND operator_id = p_operator_id
       AND status = 'approved'
       AND expires_at > now();
    IF NOT FOUND THEN RAISE EXCEPTION 'discount authorization is invalid'; END IF;
  END IF;

  v_augmented_tenders := p_tenders;
  IF v_discount > 0 THEN
    SELECT candidate.provider_name INTO v_discount_provider
      FROM unnest(ARRAY['manual','store_credit','bank_card','alipay','wechat','cash'])
        AS candidate(provider_name)
     WHERE NOT EXISTS (
       SELECT 1
         FROM jsonb_to_recordset(p_tenders)
           AS tender(provider text, amount numeric, provider_transaction_id text)
        WHERE tender.provider = candidate.provider_name
     )
     LIMIT 1;
    IF v_discount_provider IS NULL THEN
      RAISE EXCEPTION 'too many tender providers';
    END IF;
    v_augmented_tenders := p_tenders || jsonb_build_array(jsonb_build_object(
      'provider', v_discount_provider,
      'amount', v_discount,
      'provider_transaction_id', v_discount_transaction
    ));
  END IF;

  v_result := public.pos_complete_sale(
    p_shift_id, p_operator_id, p_client_op_id, p_items, v_augmented_tenders,
    p_customer_id, p_note
  );
  v_order_id := (v_result->>'order_id')::uuid;

  IF v_discount > 0 THEN
    DELETE FROM public.commerce_payment_events
     WHERE provider_event_id = v_discount_transaction;
    DELETE FROM public.commerce_payments
     WHERE order_id = v_order_id
       AND provider_transaction_id = v_discount_transaction;
  END IF;

  UPDATE public.commerce_orders
     SET discount_total = v_discount,
         total_amount = v_payable,
         discount_snapshot = coalesce(p_discount_snapshot, '{}'::jsonb),
         benefit_snapshot = coalesce(p_benefit_snapshot, '{}'::jsonb),
         authorization_id = p_authorization_id,
         updated_at = now()
   WHERE id = v_order_id;

  UPDATE public.commerce_order_items item
     SET original_unit_price = item.unit_price,
         ownership_snapshot = sku.sale_ownership,
         discount_snapshot = jsonb_build_object(
           'eligible', sku.discount_eligible AND sku.sale_ownership = 'owned',
           'order_discount_total', v_discount
         )
    FROM public.inv_skus sku
   WHERE item.order_id = v_order_id
     AND item.sku_id = sku.id;

  UPDATE public.pos_receipts
     SET payload = payload || jsonb_build_object(
       'subtotal', v_subtotal,
       'discount_total', v_discount,
       'total_amount', v_payable,
       'customer_id', p_customer_id
     )
   WHERE order_id = v_order_id;

  RETURN v_result || jsonb_build_object(
    'subtotal', v_subtotal,
    'discount_total', v_discount,
    'total_amount', v_payable
  );
END;
$function$
